// ---------------------------------------------------------------------------
// Live sync with https://dex.pbblegacy.com/
// On page load the calc loads the dex's pokedex.js and applies it directly, so
// the calc follows dex updates automatically. The three RC_*_OVERRIDES tables
// above are only the fallback if the dex can't be reached (offline, blocked,
// slow). scripts/sync_rc.js can refresh those tables from the dex.
// ---------------------------------------------------------------------------
var RC_DEX_URL = 'https://dex.pbblegacy.com/data/pokedex.js';
var RC_LIVE = null; // becomes the dex's BattlePokedex once loaded

(function loadLiveDex() {
	var hasJQ = !!(window.jQuery && window.jQuery.holdReady);
	var released = false;
	function release() {
		if (released) return;
		released = true;
		if (hasJQ) window.jQuery.holdReady(false);
	}
	// Delay $(document).ready handlers until the dex has loaded (or 3s passes),
	// so shared_controls.js needs no changes.
	if (hasJQ) window.jQuery.holdReady(true);

	var captured = {};
	var s = document.createElement('script');
	var prev = Object.getOwnPropertyDescriptor(window, 'exports');

	// Only the dex script sees an `exports` object; other scripts still see none.
	try {
		Object.defineProperty(window, 'exports', {
			configurable: true,
			get: function () { return document.currentScript === s ? captured : undefined; }
		});
	} catch (e) {}

	function restoreExports() {
		try {
			if (prev) Object.defineProperty(window, 'exports', prev);
			else delete window.exports;
		} catch (e) {}
	}

	s.onload = function () {
		RC_LIVE = (captured.BattlePokedex && Object.keys(captured.BattlePokedex).length) ? captured.BattlePokedex : null;
		restoreExports();
		release();
	};
	s.onerror = function () { restoreExports(); release(); };
	// Query string is only a cache-buster (10 minute buckets).
	s.src = RC_DEX_URL + '?v=' + Math.floor(Date.now() / 600000);
	document.head.appendChild(s);
	setTimeout(release, 3000); // never hang the calc if the dex is slow or down
})();

function applyRCLive(speciesTable) {
	var STAT = { hp: 'hp', atk: 'at', def: 'df', spa: 'sa', spd: 'sd', spe: 'sp' };
	Object.keys(RC_LIVE).forEach(function (id) {
		var e = RC_LIVE[id], sp = speciesTable[e.name], k;
		if (!sp) return; // RC-only forms the calc doesn't know are skipped
		if (e.baseStats && sp.bs) {
			for (k in STAT) {
				if (typeof e.baseStats[k] === 'number') sp.bs[STAT[k]] = e.baseStats[k];
			}
		}
		if (e.types) sp.types = e.types.slice();
		if (e.abilities) {
			sp.abilities = sp.abilities || {};
			if (e.abilities['0']) sp.abilities['0'] = e.abilities['0'];
			if (e.abilities['1']) sp.abilities['1'] = e.abilities['1'];
			else delete sp.abilities['1']; // slot removed in RC
			// Hidden ability intentionally left as the calc's vanilla data.
		}
	});
}

function applyRCOverrides(speciesTable) {
	if (RC_LIVE) { applyRCLive(speciesTable); return; }
	// Fallback: baked-in snapshot
	var name, sp, k;
	for (name in RC_STAT_OVERRIDES) {
		sp = speciesTable[name];
		if (!sp || !sp.bs) continue;
		for (k in RC_STAT_OVERRIDES[name]) sp.bs[k] = RC_STAT_OVERRIDES[name][k];
	}
	for (name in RC_TYPE_OVERRIDES) {
		sp = speciesTable[name];
		if (!sp) continue;
		sp.types = RC_TYPE_OVERRIDES[name].slice();
	}
	for (name in RC_ABILITY_OVERRIDES) {
		sp = speciesTable[name];
		if (!sp) continue;
		sp.abilities = sp.abilities || {};
		for (k in RC_ABILITY_OVERRIDES[name]) {
			if (RC_ABILITY_OVERRIDES[name][k]) sp.abilities[k] = RC_ABILITY_OVERRIDES[name][k];
			else delete sp.abilities[k];
		}
	}
}
